#include "stdlib/lapack/base/dsyconvf_rook.h"
#include "validation.h"

/**
* Converts or reverts the storage of a symmetric rook-pivoted factorization.
*
* @param layout  matrix storage layout
* @param uplo    stored matrix triangle
* @param way     'C'/'c' to convert or 'R'/'r' to revert
* @param N       matrix order
* @param A       input/output factor storage
* @param LDA     leading dimension, at least max(1,N)
* @param E       extracted or supplied off-diagonal entries of D
* @param IPIV    read-only, signed one-based LAPACK rook pivots
* @return        zero or a negative one-based argument position
*/
LAPACK_INT API_SUFFIX(c_dsyconvf_rook)( const LAPACK_LAYOUT layout, const LAPACK_UPLO uplo, const char way, const LAPACK_INT N, double *A, const LAPACK_INT LDA, double *E, const LAPACK_INT *IPIV ) {
	LAPACK_INT strideA1;
	LAPACK_INT strideA2;
	LAPACK_INT info;

	if ( layout != LAPACK_ROW_MAJOR && layout != LAPACK_COL_MAJOR ) {
		return dsyconvf_rook_error( "c_dsyconvf_rook", -1 );
	}
	if ( uplo != LAPACK_UPPER_TRIANGLE && uplo != LAPACK_LOWER_TRIANGLE ) {
		return dsyconvf_rook_error( "c_dsyconvf_rook", -2 );
	}
	if ( way != 'C' && way != 'c' && way != 'R' && way != 'r' ) {
		return dsyconvf_rook_error( "c_dsyconvf_rook", -3 );
	}
	if ( N < 0 ) {
		return dsyconvf_rook_error( "c_dsyconvf_rook", -4 );
	}
	if ( LDA < 1 || LDA < N ) {
		return dsyconvf_rook_error( "c_dsyconvf_rook", -6 );
	}
	if ( N == 0 ) {
		return 0;
	}
	if ( layout == LAPACK_COL_MAJOR ) {
		strideA1 = 1;
		strideA2 = LDA;
	} else {
		strideA1 = LDA;
		strideA2 = 1;
	}
	info = dsyconvf_rook_validate( uplo, way, N, A, strideA1, strideA2, 0, E, 1, 0, IPIV, 1, 0 );
	if ( info != 0 ) {
		if ( info == -4 ) {
			info = -5;
		} else if ( info == -5 || info == -6 || info == -7 ) {
			info = -6;
		} else if ( info >= -10 ) {
			info = -7;
		} else {
			info = -8;
		}
		return dsyconvf_rook_error( "c_dsyconvf_rook", info );
	}
	return API_SUFFIX(c_dsyconvf_rook_ndarray)( uplo, way, N, A, strideA1, strideA2, 0, E, 1, 0, IPIV, 1, 0 );
}
